defmodule ArchAstro.SDK.V1.Orgs do
  @moduledoc """
  Org API resource.
  """

  @doc """
  Search organizations

  Returns a paginated list of organizations within the authenticated app scope,
  optionally filtered by a free-text search term matched against name, slug, and
  domain (case-insensitive). Results are ordered by relevance when a search term
  is provided, and by creation time descending otherwise.

  The response includes only public-facing organization fields: ID, name, domain,
  and logo. Use the developer-scoped org endpoints to access full organization
  records.

  Pagination is offset-based. Pass `page` and `page_size` to navigate through
  results. The `has_next` and `has_prev` fields indicate whether adjacent pages
  exist.


  Successful response
  """
  @spec list(ArchAstro.SDK.Client.t(), ArchAstro.SDK.Types.Operations.GetApiV1Orgs.Params.t()) ::
          {:ok, ArchAstro.SDK.Types.Operations.GetApiV1Orgs.Response.t()}
          | {:error, ArchAstro.SDK.Error.reason()}
  def list(client, params \\ %ArchAstro.SDK.Types.Operations.GetApiV1Orgs.Params{}) do
    path = "/api/v1/orgs"

    ArchAstro.SDK.HTTP.request(client, :get, path,
      query: params,
      decode: {:ref, ArchAstro.SDK.Types.Operations.GetApiV1Orgs.Response}
    )
  end

  @doc """
  List completed organization artifacts

  Returns completed system-owned organization snapshots, newest first. Private user, team, agent and thread artifacts are excluded.

  Successful response
  """
  @spec artifacts(
          ArchAstro.SDK.Client.t(),
          String.t(),
          ArchAstro.SDK.Types.Operations.GetApiV1OrgsOrgArtifacts.Params.t()
        ) ::
          {:ok, ArchAstro.SDK.Types.Operations.GetApiV1OrgsOrgArtifacts.Response.t()}
          | {:error, ArchAstro.SDK.Error.reason()}
  def artifacts(
        client,
        org,
        params \\ %ArchAstro.SDK.Types.Operations.GetApiV1OrgsOrgArtifacts.Params{}
      ) do
    path = "/api/v1/orgs/#{ArchAstro.SDK.Path.encode(org)}/artifacts"

    ArchAstro.SDK.HTTP.request(client, :get, path,
      query: params,
      decode: {:ref, ArchAstro.SDK.Types.Operations.GetApiV1OrgsOrgArtifacts.Response}
    )
  end

  @doc """
  List an organization's linked accounts

  Returns the GitHub login each user in the organization signed in with, so
  clients can tell that a pull request's author and a Platform user are the
  same person. Users who never signed in with GitHub are absent. Any viewer
  acting within the organization can list them; other viewers get 404.

  Pass `user` to look up specific users instead of listing the whole
  organization. Results are ordered by user and paginated forward with
  `after_cursor`.


  Successful response
  """
  @spec linked_accounts(
          ArchAstro.SDK.Client.t(),
          String.t(),
          ArchAstro.SDK.Types.Operations.GetApiV1OrgsOrgLinkedAccounts.Params.t()
        ) ::
          {:ok, ArchAstro.SDK.Types.Operations.GetApiV1OrgsOrgLinkedAccounts.Response.t()}
          | {:error, ArchAstro.SDK.Error.reason()}
  def linked_accounts(
        client,
        org,
        params \\ %ArchAstro.SDK.Types.Operations.GetApiV1OrgsOrgLinkedAccounts.Params{}
      ) do
    path = "/api/v1/orgs/#{ArchAstro.SDK.Path.encode(org)}/linked_accounts"

    ArchAstro.SDK.HTTP.request(client, :get, path,
      query: params,
      decode: {:ref, ArchAstro.SDK.Types.Operations.GetApiV1OrgsOrgLinkedAccounts.Response}
    )
  end
end

